import base64, os, stat
files = {}
files['app/api/routes_portfolio_analysis.py'] = base64.b64decode('')
files['app/ingestion/portfolio_claims.py'] = base64.b64decode('')
files['app/ingestion/portfolio_members.py'] = base64.b64decode('')
files['app/models/schemas.py'] = base64.b64decode('')
files['app/scoring/rules/portfolio_analysis.py'] = base64.b64decode('')
files['app/static/index.html'] = base64.b64decode('')
files['tests/test_portfolio_analysis.py'] = base64.b64decode('')
files['start_healthcross.sh'] = base64.b64decode('')
files['start_healthcross.bat'] = base64.b64decode('')

for path, content in files.items():
    d = os.path.dirname(path)
    if d:
        os.makedirs(d, exist_ok=True)
    with open(path, "wb") as fh:
        fh.write(content)
    print(f"wrote {path} ({len(content)} bytes)")
    if path.endswith(".sh"):
        st = os.stat(path)
        os.chmod(path, st.st_mode | stat.S_IEXEC | stat.S_IXGRP | stat.S_IXOTH)
print("Done.")
